class DiagnosisProbe:
    def __init__(self, view, device):
        self.view, self.device = view, device

    def run_full_diagnosis(self, train_loader):
        was_training = self.view.model.training
        try:
            self.view.model.eval()
            with torch.inference_mode():
                metrics = existing_bounded_margin_probes(train_loader)
                for category in FOUR_CATEGORIES:
                    panel = fixed_training_prefix_panel(category, seed=42)
                    for prefix in panel:
                        candidates = fixed_unseen_candidates(prefix, seed=42)
                        original = score_with_compatibility_hooks(prefix, candidates)
                        edits = build_matched_compacted_edits(prefix)
                        for edit_name, edited_prefix in edits:
                            changed = score_with_compatibility_hooks(edited_prefix, candidates)
                            cache_paired_rank_statistics(category, edit_name, original, changed)
                metrics.update(aggregate_with_counts_and_missingness())
            return {'metrics': metrics, 'metric_definitions': explicit_definitions()}
        finally:
            self.view.model.train(was_training)
